mapper.select:
SELECT * FROM pos_campaign
WHERE deleted = 0

    AND name LIKE #{name}


    AND type = #{type}


    AND status = #{status}


    AND start_time >= #{startTimeStart}


    AND start_time <= #{startTimeEnd}


    AND end_time >= #{endTimeStart}


    AND end_time <= #{endTimeEnd}


    AND store_id = #{storeId}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT * FROM pos_campaign
WHERE deleted = 0 AND store_id = #{storeId}
ORDER BY create_time DESC

SELECT * FROM pos_campaign
WHERE deleted = 0
  AND status = 1
  AND start_time <= #{now}
  AND end_time >= #{now}
ORDER BY create_time DESC

SELECT * FROM pos_campaign
WHERE deleted = 0
  AND start_time >= #{startTime}
  AND end_time <= #{endTime}
ORDER BY start_time ASC

SELECT * FROM pos_campaign
WHERE deleted = 0
  AND status = 1
  AND start_time <= #{time}
  AND end_time >= #{time}
ORDER BY create_time DESC

SELECT * FROM pos_campaign
WHERE deleted = 0 AND type = #{type}
ORDER BY create_time DESC

SELECT * FROM pos_campaign
WHERE deleted = 0 AND status = #{status}
ORDER BY create_time DESC

mapper.update:
UPDATE pos_campaign
SET status = #{afterStatus}, updated_at = NOW()
WHERE deleted = 0
  AND status = #{beforeStatus}
  AND end_time <= #{time}
